number_of_digit_one.brute:
total = 0
for each i from 0 to n:
    for each character of i written out:
        if it is "1": total += 1
return total

number_of_digit_one.optimal:
total = 0, place = 1   (1, 10, 100, ...)
while place <= n:
    high = n / (place * 10), cur = digit of n at place, low = n mod place
    total += high * place   (each full cycle above shows a 1 for `place` numbers)
    if cur > 1: total += place   (the partial cycle passed its whole run of 1s)
    else if cur == 1: total += low + 1   (inside the run of 1s: ...1000 up to n)
    place *= 10
return total

max_points_on_a_line.brute:
best = min(n, 2)
for each pair of points i < j:
    dx, dy = point j - point i
    on_line = 0
    for each point k:
        kx, ky = point k - point i
        if dx * ky - dy * kx == 0: on_line += 1   (cross product 0: k is on the line through i, j)
    best = max(best, on_line)
return best

max_points_on_a_line.optimal:
best = 1
for each point i:
    counts = empty dict reduced direction (dx, dy) -> count
    for each point j > i:   (pairs with j < i were counted from anchor j)
        dx, dy = point j - point i
        divide dx and dy by gcd(dx, dy)   (reduce to a canonical direction)
        if dx < 0 or (dx == 0 and dy < 0): negate both   (one sign per direction)
        counts[(dx, dy)] += 1
    for each key in counts: best = max(best, counts[key] + 1)   (+1 for the anchor itself)
return best

perfect_rectangle.brute:
for each pair of rectangles A, B:
    if A and B overlap in x and in y with positive area: return False
min_x, min_y, max_x, max_y = bounding box of all rectangles
area = sum of (x2 - x1) * (y2 - y1) over all rectangles
return area == (max_x - min_x) * (max_y - min_y)

perfect_rectangle.optimal:
corners = empty set, area = 0
for each rectangle (x1, y1, x2, y2):
    area += (x2 - x1) * (y2 - y1)
    for each of its 4 corner points p:
        if p in corners: remove p   (a corner shared by 2 or 4 rectangles cancels out)
        else: add p
min_x, min_y, max_x, max_y = bounding box of all rectangles
outline = the 4 corners of the bounding box
return corners == outline and area == (max_x - min_x) * (max_y - min_y)

valid_number.brute:
digits_only(t): t is non-empty and every character is a digit
drop_sign(t): t without one leading "+" or "-"
is_integer(t): digits_only(drop_sign(t))
is_decimal(t):
    t = drop_sign(t)
    if "." not in t: return digits_only(t)
    before, after = the parts around the first "."   (re-scans both halves)
    if before is non-empty and not digits_only(before): return False
    if after is non-empty and not digits_only(after): return False
    return before + after is non-empty
for each index k with char c in s:   (split at the exponent, if any)
    if c is "e" or "E": return is_decimal(s[0..k)) and is_integer(s[k + 1..])
return is_decimal(s)

valid_number.optimal:
seen_digit = seen_dot = seen_exp = false
for each index i with char c in s:
    if c is a digit: seen_digit = true
    else if c is "+" or "-":
        if i > 0 and s[i - 1] is not "e" or "E": return false   (a sign only at start or after e)
    else if c == ".":
        if seen_dot or seen_exp: return false   (one dot, and never inside the exponent)
        seen_dot = true
    else if c is "e" or "E":
        if seen_exp or not seen_digit: return false   (one e, and it needs a mantissa)
        seen_exp = true, seen_digit = false   (the exponent needs its own digits)
    else: return false
return seen_digit

longest_happy_prefix.brute:
for each length from n - 1 down to 1:   (longest candidate first)
    if s[0..length) == s[n - length..]:   (a fresh O(length) comparison each time)
        return s[0..length)
return ""

longest_happy_prefix.optimal:
fail = n zeros   (fail[i] = longest proper border of s[0..i])
for i from 1 to n - 1:
    k = fail[i - 1]   (border so far; try to extend it by s[i])
    while k > 0 and s[i] != s[k]:
        k = fail[k - 1]   (mismatch: shrink to the border of the border)
    if s[i] == s[k]: k += 1
    fail[i] = k
return s[0..fail[n - 1])

shortest_palindrome.brute:
for each length from n down to 1:   (longest prefix first)
    prefix = s[0..length)
    if prefix reads the same reversed:   (a fresh O(length) check every time)
        return reverse of s[length..] + s
return s

palindrome_pairs.brute:
pairs = empty list
for each ordered pair (i, j) with i != j:
    if words[i] + words[j] reads the same reversed:
        append [i, j] to pairs
return pairs

palindrome_pairs.optimal:
where = dict reversed word -> its index
pairs = empty list
for each index i with word:
    for each cut from 0 to length of word:   (word = front + back)
        front = word[0..cut), back = word[cut..]
        if front is a palindrome and back in where and where[back] != i:
            append [where[back], i]   (reverse(back) + front + back reads the same both ways)
        if cut < length and back is a palindrome and front in where and where[front] != i:
            append [i, where[front]]   (front + back + reverse(front); cut < length skips a repeat)
return pairs
